"""Build project-hosted technical notes from the checked-in benchmark evidence."""
from pathlib import Path
import json
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, KeepTogether
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.colors import HexColor
from reportlab.lib.enums import TA_LEFT

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'site/artifacts'
OUT.mkdir(parents=True,exist_ok=True)
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='TitleYC',fontName='Helvetica',fontSize=30,leading=34,textColor=HexColor('#172b24'),spaceAfter=22))
styles.add(ParagraphStyle(name='DeckYC',fontName='Helvetica',fontSize=12,leading=19,textColor=HexColor('#536158'),spaceAfter=20))
styles.add(ParagraphStyle(name='HeadingYC',fontName='Helvetica-Bold',fontSize=15,leading=20,textColor=HexColor('#172b24'),spaceBefore=17,spaceAfter=9))
styles.add(ParagraphStyle(name='BodyYC',fontName='Helvetica',fontSize=10.5,leading=16,spaceAfter=11,textColor=HexColor('#243d2b')))
styles.add(ParagraphStyle(name='SmallYC',fontName='Helvetica',fontSize=8.5,leading=13,spaceAfter=9,textColor=HexColor('#536158')))
styles.add(ParagraphStyle(name='CodeYC',fontName='Courier',fontSize=8,leading=13,backColor=HexColor('#edf1e5'),borderPadding=9,spaceAfter=12))
def P(text,kind='BodyYC'):return Paragraph(text,styles[kind])
def H(text):return P(text,'HeadingYC')
def table(rows,widths):
 t=Table([[P(str(c),'SmallYC') for c in row] for row in rows],colWidths=widths,hAlign='LEFT')
 t.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('BACKGROUND',(0,0),(-1,0),HexColor('#e7eddb')),('LINEBELOW',(0,0),(-1,-1),.4,HexColor('#cbd4bf')),('TOPPADDING',(0,0),(-1,-1),9),('BOTTOMPADDING',(0,0),(-1,-1),6)]))
 return t
def chrome(canvas,doc):
 w,h=doc.pagesize;canvas.setFillColor(HexColor('#172b24'));canvas.rect(0,h-10,w,10,fill=1,stroke=0)
 canvas.setFont('Helvetica',8);canvas.setFillColor(HexColor('#536158'));canvas.drawString(48,29,'YOUR CATALYST / PROJECT TECHNICAL NOTE / 21 OCT 2026');canvas.drawRightString(w-48,29,str(doc.page))
def write(name,story,title):
 SimpleDocTemplate(str(OUT/name),pagesize=(595.28,841.89),leftMargin=48,rightMargin=48,topMargin=45,bottomMargin=50,title=title,author='Your Catalyst',subject='Project-hosted technical note; not a peer-reviewed publication').build(story,onFirstPage=chrome,onLaterPages=chrome)

s=json.loads((ROOT/'evidence/josaa-static.json').read_text());d=json.loads((ROOT/'evidence/josaa-dynamic.json').read_text())
story=[P('JoSAA allocation audit','TitleYC'),P('Methods, counterfactual results and limitations','DeckYC'),P('STATUS: Project-hosted technical note. This is an implementation and simulation audit, not a new proof of applicant DSIC or an evaluation of real student outcomes.','SmallYC'),H('1. The question'),P('How do an applicant\'s round decisions interact with vacancies created by other applicants withdrawing? Student-proposing deferred acceptance is already known to satisfy applicant dominant-strategy incentive compatibility (DSIC) under the standard single-round assumptions. This portfolio uses that result as a baseline and studies a simplified multi-round mechanism through paired counterfactuals.'),H('2. Headline checks'),table([['Check','Observed result','Interpretation'],['Static reporting','0 profitable deviations / 1,080 tested','60 applicants, 17 programs; one synthetic cohort.'],['Freeze versus Float','50 / 50 trials missed an upgrade under Freeze','One selected applicant; identical withdrawal in both worlds.'],['Dynamic workload','201 matching runs','One target-selection allocation, then 50 pairs x 2 rounds.']],[115,165,219]),H('3. What the data actually represents'),P('The input file data/raw/sample_josaa_cutoffs.csv is a sample opening/closing-rank table in the repository. It does not include a verified official provenance URL or a year. Candidate preference lists and utilities are synthetic. The reported checks therefore concern constructed markets derived from this sample, not real submitted JoSAA preferences or observed applicant regret.'),P('The current calibration uses OPEN-category rows from round 1. Capacity is approximated from each rank-band width, with a minimum of one seat. Program utilities depend on closing-rank order, creating a strong shared preference structure. The dynamic audit does not test quota-specific clearing rates.','SmallYC'),PageBreak(),P('The paired experiment','TitleYC'),H('4. Reproduce the decision timing'),P('The dynamic script constructs 80 synthetic candidates over 17 programs. A round-1 allocation selects the first allocated applicant who did not receive their first choice: applicant_005. Four allocated candidates have higher merit priority. Each trial samples exactly one of those four for withdrawal before round 2.'),P('Both counterfactual worlds use the same initial cohort, program capacities and sampled withdrawal. In the Float world the target retains upgrade eligibility. In the Freeze world the target commits at the end of round 1 and restricts their next-round options to the held seat. The script uses the current engine functions rather than the removed class API.'),P('There are only four possible single-withdrawal sets in this design, sampled repeatedly over 50 trials with seed 1337. The denominator is 50 paired trials for one selected applicant, not 50 different students. All 50 produce a missed upgrade for the frozen target. This conditional result must not be turned into a population-wide percentage.'),H('5. Inspectable outputs'),P('evidence/josaa-static.json records cohort size, tested deviations, profitable deviations and assignment counts. evidence/josaa-dynamic.json additionally records the target, each withdrawal set, both final matches, preference-rank differences and utility differences. Both files contain SHA-256 fingerprints for the scripts, engine and input sample.'),H('6. Checks and implementation detail'),P('The regression suite checks hand-solved allocations, vacancy chains, action filtering and the agreement between a retained student\'s current_match and the program allocation. A metadata bug for later higher-priority proposals was repaired while verifying these benchmarks. The finite static audit enumerates truncations and two adjacent top-choice swaps per applicant.'),P('A matching pass permits at most S x P distinct proposals. This Python reference uses a list queue and sorts the retained candidate pool on each proposal; queue removal and capacity-dependent sorting add overhead. It is an inspectable reference implementation, not an optimized production allocator.'),PageBreak(),P('Reproduction & boundaries','TitleYC'),H('7. Run from the repository root'),P('python -m pytest -q<br/>python -m scripts.benchmark_manipulability --json evidence/josaa-static.json<br/>python -m scripts.audit_dynamic_strategies --json evidence/josaa-dynamic.json','CodeYC'),P('Python standard-library kernels; pytest for checks. The browser sandbox is a separate JavaScript/Tailwind interface. The static research portfolio uses HTML, CSS, JavaScript ES modules and SVG, delivered with GitHub Pages.'),H('8. What the result does not establish'),P('The sample table is not a complete official seat matrix. Submitted preferences, horizontal and supernumerary rules, fees, risk preferences and alternative admissions are not estimated. The benchmark isolates a two-round, OPEN-category construction; the reservation component has separate tests and is not part of this dynamic estimate.'),P('No Round-4 cutoff, category-specific effect, 50,000-candidate experiment or general regret rate is claimed. The static finite check is consistent with established DSIC theory under the reference assumptions; it neither proves the theorem nor certifies the complete real admissions mechanism.'),H('9. Next extensions'),P('Archive verifiable official inputs and their provenance; diversify preference models; vary target selection and withdrawal rules; compare multiple seeds and cohort sizes; implement and test richer category and timing rules. User studies and independent review would provide different evidence from numerical tests and should be reported separately.'),H('Sources & artifacts'),P('<link href="https://github.com/thetarocks/catalyst-lab" color="#285b42">github.com/thetarocks/catalyst-lab</link><br/><link href="https://lab.yourcatalyst.in" color="#285b42">lab.yourcatalyst.in</link><br/>Primary implementation: core/deferred_acceptance.py; core/josaa_engine.py; core/agents.py.<br/>Benchmark outputs: evidence/josaa-static.json; evidence/josaa-dynamic.json.','SmallYC'),P('The implementation and notes were developed with AI coding assistance. Distinguish understood, personally validated contributions from tool-assisted implementation work when describing the portfolio.','SmallYC')]
write('josaa-technical-note.pdf',story,'JoSAA allocation audit - methods, results and limitations')

cases=json.loads((ROOT/'site/evidence/sybil-boundaries.json').read_text())['cases']
story=[P('Governance & Sybil boundaries','TitleYC'),P('An analytical companion to the DAO project','DeckYC'),P('STATUS: Project-hosted technical note. The linked SSRN preprint is a separate public research artifact. This document is not a Zenodo archive or a peer-reviewed article.','SmallYC'),H('1. Public paper and separate model'),P('The Arbitrum preprint reports outcome changes in 4 of 15 selected proposals under square-root reweighting. See <link href="https://papers.ssrn.com/sol3/papers.cfm?abstract_id=7103878" color="#285b42">SSRN abstract 7103878</link>. The identity-splitting preview below is a separate fixed-budget calculation, not a replication of the paper\'s ballot-level analysis.'),H('2. Derive the equal-split amplification'),P('Let T be a fixed token budget and W = sqrt(T) its unsplit square-root weight. Splitting equally across k identities gives total weight k sqrt(T/k) = sqrt(k) W. The additional weight is (sqrt(k) - 1) W. Equal splitting maximizes total square-root weight for fixed k and T, assuming fractional holdings and no identity costs.'),P('If G is the existing winning-side minus losing-side score gap, with the attacker\'s unsplit weight already included on the losing side, strict reversal requires (sqrt(k) - 1) W &gt; G. For W &gt; 0 and G &gt;= 0, the smallest integer k is floor((1 + G/W)^2) + 1. Equality creates a tie, not a strict reversal.'),H('3. Algebraic checks of published summaries'),table([['Summary label','W','G','Strict k minimum']]+[[c['name'],f"{c['W']:,.2f}",f"{c['G']:,.2f}",c['computed_strict_k_min']] for c in cases],[186,90,115,108]),PageBreak(),P('Provenance & limitations','TitleYC'),H('4. What was checked'),P('The four W/G pairs are hard-coded in dao-sybil-resilience/run_sybil_pipeline.py. The site recomputes each integer boundary and verifies that the additional weight is above G at k and no greater than G at k - 1. evidence/sybil-boundaries.json records the values, derivation, source URL and source-file SHA-256.'),P('The companion arbitrum-quadratic-voting-simulation repository contains Snapshot GraphQL collection, vote reweighting, concentration metrics and reconstruction checks. Proposal metadata is committed. A full frozen raw-ballot export is not committed in the inspected repositories, so the four W/G summaries cannot be independently reconstructed from those repositories alone.'),H('5. Interpretation boundaries'),P('A wallet is not necessarily a person. Splitting can involve transaction fees, identity requirements, minimum balances, delegation constraints and limits on eligible balances. The preview assumes these away, holds the opposing tally fixed and permits equal splitting of a fixed budget. It does not estimate the cost or feasibility of an actual attack.'),P('The browser preview and the phase-boundary checks are analytical calculations. They do not establish that a specific minority token share can overturn a real proposal through three wallets, nor that changing a vote-weight rule leaves voter behavior unchanged.'),H('6. Reproduce and extend'),P('python -m pytest tests/test_benchmark_evidence.py -q<br/>python scripts/build_portfolio.py','CodeYC'),P('Next steps: archive the exact vote records with proposal IDs and timestamps; verify page boundaries and reconstruction totals; publish the frozen outputs; and add identity-cost, eligibility and integer-token constraints before interpreting real-world exploitability.'),H('Source links'),P('<link href="https://github.com/thetarocks/dao-sybil-resilience" color="#285b42">github.com/thetarocks/dao-sybil-resilience</link><br/><link href="https://github.com/thetarocks/arbitrum-quadratic-voting-simulation" color="#285b42">github.com/thetarocks/arbitrum-quadratic-voting-simulation</link><br/><link href="https://papers.ssrn.com/sol3/papers.cfm?abstract_id=7103878" color="#285b42">papers.ssrn.com - abstract 7103878</link>','SmallYC')]
write('sybil-technical-note.pdf',story,'Governance and Sybil boundaries - analytical companion')
